return ['domain'=>'zinn-chat','plural-forms'=>'nplurals=3; plural=(n%10==1 && n%100!=11 ? 0 : n%10>=2 && n%10<=4 && (n%100<10 || n%100>=20) ? 1 : 2);','language'=>'sr_RS','project-id-version'=>'zinn-chat','pot-creation-date'=>'2026-09-25T22:28:09+00:00','po-revision-date'=>'2026-09-25T22:28:09+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Zinn® Chat'=>'Zinn® Chat','https://zinndigital.com/wordpress-plugins/zinn-chat'=>'https://zinndigital.com/wordpress-plugins/zinn-chat','A fast, privacy-respecting live chat for your website. Answers visitors with AI when you are busy, hands them to you when they need a person, and emails you anything you miss. Under 10 KB on the page and no requests at all until somebody opens it.'=>'Brz i privatnost usmeren lajv čet za vaš veb-sajt. Odgovara posetiocima pomoću veštačke inteligencije kada ste zauzeti, prenosi ih vama kada im je potrebna stvarna osoba i šalje vam e-poštu o svemu što propustite. Manji od 10 KB na stranici i bez ikakvih zahteva dok ga neko ne otvori.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','Settings'=>'Podešavanja','That does not look like a Zinn® Chat key. Copy it from the Live chat page of your Zinn Digital® dashboard — it starts with zc_.'=>'To ne liči na Zinn® Chat ključ. Kopirajte ga sa stranice Uživo ćaskanje na vašoj Zinn Digital® kontrolnoj tabli — počinje sa zc_.','Add your chat key before switching the chat on — without it there is nothing for the widget to connect to.'=>'Dodajte svoj ključ za ćaskanje pre nego što uključite ćaskanje — bez njega vidžet nema sa čim da se poveže.','Live chat for this site. Visitors get an answer straight away, you get anything you miss by email, and the whole thing is under 10 KB on the page.'=>'Živi chat za ovaj sajt. Posetioci dobijaju odgovor odmah, vi dobijate sve što propustite putem e-pošte, a cela stvar zauzima manje od 10 KB na stranici.','The chat is live on this site.'=>'Ćaskanje je uživo na ovom sajtu.','The chat is switched off. Nothing is loaded on your site.'=>'Čet je isključen. Ništa nije učitano na vašem sajtu.','Chat key'=>'Ključ za ćaskanje','Copy this from the Live chat page of your %s.'=>'Kopirajte ovo sa stranice za uživo ćaskanje (Live chat) vašeg %s.','Zinn Digital® dashboard'=>'Zinn Digital® kontrolna tabla','Show the chat'=>'Prikaži ćaskanje','Show the chat window to visitors of this site'=>'Prikažite prozor za ćaskanje posetiocima ovog sajta','Until you tick this, the plugin adds nothing at all to your pages — no script, no cookie, no requests.'=>'Dok ovo ne označite, dodatak ne dodaje apsolutno ništa na vaše stranice – ni skriptu, ni kolačić, ni zahteve.','%s — guides and services'=>'%s — vodiči i usluge','User guides'=>'Korisnička uputstva','Read the %s user guide'=>'Pročitajte %s korisničko uputstvo','Hide this'=>'Sakrij ovo','Zinn® hosting for WordPress'=>'Zinn® hosting za WordPress','LiteSpeed, daily backups, free migration and a control panel built for people who run more than one site.'=>'LiteSpeed, dnevne rezervne kopije, besplatna migracija i kontrolna tabla napravljena za ljude koji vode više od jednog sajta.','The Zinn® marketplace'=>'Zinn® pijaca','Buy and sell established sites, domains and link placements, with the money held safely until both sides are happy.'=>'Kupujte i prodajite već uspostavljene sajtove, domene i plasmane linkova, uz sigurno čuvanje novca sve dok obe strane ne budu zadovoljne.','Zinn Hub® — hire people who do this for a living'=>'Zinn Hub® — angažujte ljude koji se time bave profesionalno','Our global freelance marketplace: browse over 10,000 ready-made services from writers, designers, developers and SEOs, or post a project and let them bid.'=>'Naše globalno tržište frejlansera: pregledajte preko 10.000 gotovih usluga pisaca, dizajnera, programera i SEO stručnjaka, ili objavite projekat i dozvolite im da licitiraju.','See the Zinn Digital® release notes.'=>'Pogledajte beleške o izdanju za Zinn Digital®.','The downloaded update failed its integrity check and was not installed.'=>'Preuzeto ažuriranje nije prošlo proveru integriteta i nije instalirano.','Everything here keeps working for nothing, for ever. Pro is for when one person answering, and a month of history, stops being enough.'=>'Sve ovde nastavlja da radi besplatno, zauvek. Pro je za trenutke kada jedna osoba koja odgovara i mesec dana istorije prestanu da budu dovoljni.','As many colleagues answering at once as you like — the free plugin allows one.'=>'Onoliko kolega koji odgovaraju u isto vreme koliko želite — besplatni dodatak dozvoljava jednog.','Every conversation kept for ever, instead of thirty days.'=>'Svaka konverzacija se čuva zauvek, umesto trideset dana.','Your own name on the chat window, with ours removed.'=>'Vaše sopstveno ime u prozoru za ćaskanje, uz uklonjeno naše.','Saved replies, transfer a conversation to a colleague, and business hours.'=>'Sačuvani odgovori, prenos razgovora kolegi i radno vreme.','5,000 AI answers a month rather than 100.'=>'5.000 AI odgovora mesečno umesto 100.','Choose exactly which pages the chat appears on — or hide it from the checkout.'=>'Izaberite tačno na kojim stranicama se ćaskanje prikazuje — ili ga sakrijte sa stranice za naplatu.','One licence covers three of your sites; ten-site licences are available.'=>'Jedna licenca pokriva tri vaša sajta; dostupne su licence za deset sajtova.','See what Pro costs'=>'Pogledajte koliko košta Pro','Already host a site with Zinn Digital®? Pro is included free — your key is on the %s.'=>'Vec hostujete sajt na Zinn Digital®-u? Pro je besplatno uključen — vaš ključ se nalazi na %s.','Licences page of your dashboard'=>'Stranica sa licencama na vašoj kontrolnoj tabli','Your licence is active.'=>'Vaša licenca je aktivna.','Your licence has run out but everything still works for a short while. Renew it to keep receiving updates.'=>'Vaša licenca je istekla, ali sve i dalje radi još kratko vreme. Obnovite je da biste nastavili da primate ažuriranja.','We do not recognise that licence key. Copy it again from the Licences page of your Zinn Digital® dashboard.'=>'Ne prepoznajemo taj licencni ključ. Kopirajte ga ponovo sa stranice Licences na vašoj Zinn Digital® kontrolnoj tabli.','That key is for a different Zinn® plugin. The one you want is on the Licences page of your dashboard, next to Zinn® Chat Pro.'=>'Taj ključ je za drugi Zinn® dodatak. Onaj koji vam treba nalazi se na stranici Licences vaše kontrolne table, pored Zinn® Chat Pro.','Your licence has expired. Renew it from your Zinn Digital® dashboard to switch the Pro features back on.'=>'Vaša licenca je istekla. Obnovite je sa svoje Zinn Digital® kontrolne table da biste ponovo uključili Pro funkcije.','This licence has been cancelled.'=>'Ova licenca je otkazana.','This licence is on hold. Please get in touch and we will sort it out.'=>'Ova licenca je na čekanju. Molimo vas da stupite u kontakt sa nama i mi ćemo to rešiti.','There is a billing problem on your Zinn Digital® account. Once it is settled the licence works again straight away.'=>'Postoji problem sa naplatom na vašem Zinn Digital® nalogu. Čim se to reši, licenca će odmah ponovo raditi.','This licence came free with your Zinn® hosting, and that hosting has ended. Buy a licence, or start hosting with us again, to switch Pro back on.'=>'Ova licenca je došla besplatno uz vaš Zinn® hosting, a taj hosting je završen. Kupite licencu ili ponovo počnite da koristite naš hosting da biste ponovo uključili Pro.','Every site on this licence is in use. Release one below, or upgrade to cover more sites.'=>'Svaki sajt na ovoj licenci je u upotrebi. Oslobodite jedan ispod ili nadogradite da biste obuhvatili više sajtova.','We could not confirm your licence just now. Nothing has changed on your site; we will try again shortly.'=>'Trenutno nismo mogli da potvrdimo vašu licencu. Na vašem sajtu se ništa nije promenilo; pokušaćemo ponovo uskoro.','You do not have permission to manage licences on this site.'=>'Nemate dozvolu za upravljanje licencama na ovom sajtu.','Your Pro licence'=>'Vaša Pro licenca','Licence key'=>'Licencni ključ','Copy it from the Licences page of your %s.'=>'Kopirajte ga sa stranice Licences vašeg %s.','Renews on %s.'=>'Obnavlja se dana %s.','Using %1$d of %2$d sites.'=>'Korišćenje %1$d od %2$d sajtova.','In use on: %s. Release one from your dashboard, then try again.'=>'Koristi se na: %s. Oslobođeni jednu sa kontrolne table, pa pokušajte ponovo.','Save licence'=>'Sačuvaj licencu','Remove it from this site'=>'Uklonite ga sa ovog sajta','Where the chat appears'=>'Gde se ćaskanje prikazuje','Show it'=>'Prikaži','Everywhere on this site'=>'Svuda na ovom sajtu','Only on the pages I choose below'=>'Samo na stranicama koje izaberem u nastavku','Everywhere except the pages I choose below'=>'Svuda osim na stranicama koje izaberem u nastavku','Page or post IDs'=>'ID-ovi stranica ili objava','Separate them with commas. The ID is in the address bar while you edit a page.'=>'Odvojite ih zarezima. ID se nalazi u adresnoj traci dok uređujete stranicu.','Whole content types'=>'Сви типови садржаја','Signed-in visitors'=>'Prijavljeni posetioci','Hide the chat from people who are signed in to this site'=>'Sakrijte ćaskanje od ljudi koji su prijavljeni na ovaj sajt','Save where it appears'=>'Sačuvaj gde se nalazi']];